package engine_test

import (
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"

	"github.com/zcayou/go-tools/golangci/zenum/engine"
)

var _ = Describe("declarations", func() {
	// Every enum in the fixture is exported, so each readable String form passes
	// only by being read: an unread one would draw unreadable-name. The stringer
	// layouts in runs_string.go were generated by running stringer.
	It("reads each readable form, and judges what the names say", func() {
		Expect(analyzeFixture("forms", engine.Config{})).To(Equal([]string{
			"forms.go:84:2: ambiguous-name: example.com/forms.Ambiguous",
			"forms.go:85:2: ambiguous-name: example.com/forms.Ambiguous",
			"forms.go:86:2: ambiguous-name: example.com/forms.Ambiguous",
			"forms.go:104:20: unreadable-name: example.com/forms.Formatted",
			"forms.go:118:6: unnamed: example.com/forms.Nameless",
			"forms.go:124:6: unnamed: example.com/forms.Pointer",
			"forms.go:131:6: string-enum: example.com/forms.Mode",
		}))
	})

	It("says what each declaration finding means", func() {
		unnamed := "is visible outside its package but has no String() string on a value receiver"
		Expect(messages("forms", engine.Config{})).To(Equal(map[string]string{
			"forms.go:84:2": "ambiguous-name: forms.Ambiguous's String gives AmbiguousB the token \"same\", " +
				"as it does AmbiguousA",
			"forms.go:85:2": "ambiguous-name: forms.Ambiguous's String gives AmbiguousC an empty token",
			"forms.go:86:2": "ambiguous-name: forms.Ambiguous's String gives AmbiguousD no token",
			"forms.go:104:20": "unreadable-name: forms.Formatted's String is in no readable form, so the names " +
				"it publishes go unverified",
			"forms.go:118:6": "unnamed: forms.Nameless " + unnamed,
			"forms.go:124:6": "unnamed: forms.Pointer " + unnamed,
			"forms.go:131:6": "string-enum: forms.Mode has a string underlying type, so its tokens are its identities; " +
				"make it ordinal and name it with String",
		}))
	})

	// phase is private: its own String handing a value to fmt does not make
	// it visible.
	It("reports a visible enum's zero member, unless zero is its documented default", func() {
		policy := engine.Config{ZeroDefaults: []string{"example.com/zero.Policy"}}

		Expect(analyzeFixture("zero", policy)).To(Equal([]string{
			"zero.go:9:2: zero-member: example.com/zero.Kind",
			"zero.go:44:6: string-enum: example.com/zero.Mode",
			"zero.go:47:2: zero-member: example.com/zero.Mode",
		}))
		Expect(messages("zero", engine.Config{})).To(HaveKeyWithValue("zero.go:9:2",
			"zero-member: KindNone is zero.Kind's zero value, which an unset field also holds; start the members above zero"))
	})

	It("reports the zero member of an enum no zero-defaults entry lists", func() {
		Expect(analyzeFixture("zero", engine.Config{})).To(
			ContainElement("zero.go:28:2: zero-member: example.com/zero.Policy"))
	})

	// Flags would draw unnamed and token-decision, Bytes unnamed,
	// forged-conversion and token-decision, and Kind's sentinel ambiguous-name.
	It("judges no flag set, no quantity and no count sentinel", func() {
		Expect(analyzeFixture("shapes", engine.Config{})).To(BeNil())
	})

	It("takes an open enum out of every rule", func() {
		open := engine.Config{OpenEnums: []string{"example.com/open/wire.ID", "example.com/open/wire.Code"}}

		Expect(analyzeFixture("open", engine.Config{})).To(Equal([]string{
			"open.go:10:5: forged-conversion: example.com/open/wire.ID",
			"open.go:10:16: token-decision: example.com/open/wire.ID",
			"open.go:12:21: numeric-verb: example.com/open/wire.Code",
			"open.go:13:9: forged-conversion: example.com/open/wire.ID",
			"open.go:13:21: forged-conversion: example.com/open/wire.Code",
			"wire/wire.go:4:6: string-enum: example.com/open/wire.ID",
			"wire/wire.go:7:2: zero-member: example.com/open/wire.ID",
			"wire/wire.go:12:6: unnamed: example.com/open/wire.Code",
			"wire/wire.go:15:2: zero-member: example.com/open/wire.Code",
		}))
		Expect(analyzeFixture("open", open)).To(BeNil())
	})

	DescribeTable("fails on an exception that suppresses nothing",
		func(cfg engine.Config, expected *engine.ExceptionError) {
			Expect(analyzeError("zero", cfg)).To(MatchError(expected))
		},
		Entry("an open type that is no enum",
			engine.Config{OpenEnums: []string{"example.com/zero.Missing"}},
			&engine.ExceptionError{
				Setting: engine.SettingOpenEnums, Fault: engine.FaultNotEnum, Type: "example.com/zero.Missing",
			}),
		Entry("a zero default that is no enum",
			engine.Config{ZeroDefaults: []string{"example.com/zero.missing"}},
			&engine.ExceptionError{
				Setting: engine.SettingZeroDefaults, Fault: engine.FaultNotEnum, Type: "example.com/zero.missing",
			}),
		Entry("a zero default for an enum an open entry took out",
			engine.Config{
				OpenEnums:    []string{"example.com/zero.Policy"},
				ZeroDefaults: []string{"example.com/zero.Policy"},
			},
			&engine.ExceptionError{
				Setting: engine.SettingZeroDefaults, Fault: engine.FaultNotEnum, Type: "example.com/zero.Policy",
			}),
		Entry("a zero default for an enum with no member at zero",
			engine.Config{ZeroDefaults: []string{"example.com/zero.Count"}},
			&engine.ExceptionError{
				Setting: engine.SettingZeroDefaults, Fault: engine.FaultNoZeroMember, Type: "example.com/zero.Count",
			}),
	)
})
